import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"应用简介","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1794296442000}`),a={name:`introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="应用简介" tabindex="-1">应用简介 <a class="header-anchor" href="#应用简介" aria-label="Permalink to “应用简介”">​</a></h1><p>本页说明 XiHan.BasicApp 的定位、核心约定、技术栈与阅读路径，适用于初次了解本项目的读者。</p><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to “定位”">​</a></h2><p>XiHan.BasicApp 是曦寒生态的企业级中后台应用。后端基于 XiHan.Framework，按框架的「能力包 + 操作契约」组织；前端基于 XiHan.UI，接口层由后端导出的 <code>openapi.json</code> 生成。</p><p>它有两个用途：</p><ul><li>XiHan.Framework 的参考应用：只用框架的一等概念（<code>IFeature</code> 能力包、<code>[Operation]</code> 操作、管道阶段中间件、Provider、消息键），不另建平行机制。</li><li>新项目的起点：已包含多租户、身份与会话、RBAC 及其收窄规则、组织机构、参数与字典、文件、通知、审计日志、任务调度与开放平台等中后台的通用部分，另有工作台、工作流、在线聊天、打印模板、代码生成与 AI 几个可选模块。</li></ul><h2 id="核心约定" tabindex="-1">核心约定 <a class="header-anchor" href="#核心约定" aria-label="Permalink to “核心约定”">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>约定</th></tr></thead><tbody><tr><td>接口</td><td>一个方法一个 <code>[Operation(&quot;&lt;资源&gt;.&lt;动词&gt;&quot;)]</code>，路由由操作 ID 推导，前缀 <code>/api</code>；不写 Controller</td></tr><tr><td>响应</td><td>成功即 DTO；失败是 RFC 9457 <code>application/problem+json</code>，按 <code>code</code> 分支</td></tr><tr><td>协议</td><td>同一份操作按 <code>Expose</code> 发布到 HTTP、gRPC（内部调用）与 MCP（AI 工具）</td></tr><tr><td>主键与租户</td><td>主键 UUID v7；租户 ID 是字符串；平台库实体不实现 <code>IMultiTenant</code>，租户库实体可随租户分库</td></tr><tr><td>权限码</td><td><code>&lt;包&gt;.&lt;资源&gt;.&lt;动作&gt;</code> 点分三段；按钮直接用操作的权限码</td></tr><tr><td>前端接口层</td><td>由 <code>openapi.json</code> 生成类型、操作客户端、权限码与枚举，不手写</td></tr><tr><td>表结构</td><td><code>Schema/&lt;版本&gt;/*.sql</code> 加版本台账，启动时自动升级；新库经 <code>schema upgrade</code> + <code>seed</code> 初始化（见<a href="./backend/upgrade">表结构升级</a>）</td></tr></tbody></table><p>取舍与理由见<a href="./why">设计取舍</a>，逐项能力见<a href="./features">功能清单</a>，版本变化见<a href="./changelog">更新日志</a>。</p><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to “阅读路径”">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>文档</th></tr></thead><tbody><tr><td>在本机运行</td><td><a href="./dev-environment">开发环境</a> → <a href="./getting-started">快速开始</a></td></tr><tr><td>了解整体结构</td><td><a href="./overview">系统概述</a> → <a href="./project-structure">目录结构</a> → <a href="./backend/introduction">后端架构总览</a></td></tr><tr><td>新增操作或页面</td><td><a href="./backend/development">后端开发流程</a> · <a href="./frontend/development">前端开发流程</a></td></tr><tr><td>对接接口</td><td><a href="./api-guide">接口对接指南</a></td></tr><tr><td>查阅配置项</td><td><a href="./configuration">配置参考</a></td></tr><tr><td>部署与升级</td><td><a href="./deployment">部署</a> · <a href="./backend/upgrade">表结构升级</a></td></tr></tbody></table><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>技术</th></tr></thead><tbody><tr><td>后端</td><td>.NET 10、XiHan.Framework（<code>Profiles.Full</code>）、SqlSugar、PostgreSQL（缺省）、JWT（HS256）、SignalR、Scriban</td></tr><tr><td>协议</td><td>HTTP（OpenAPI 3.1 + Scalar）、gRPC（内部服务调用）、MCP</td></tr><tr><td>前端</td><td>Vue、Vite、TypeScript、Pinia、Vue Router、vue-i18n（10 种区域）、Tailwind CSS、XiHan.UI</td></tr><tr><td>测试</td><td>xUnit（Microsoft.Testing.Platform）、Vitest</td></tr></tbody></table><p>依赖版本见 <code>backend/Directory.Packages.props</code> 与 <code>frontend/package.json</code>。</p><h2 id="与-xihan-framework-的关系" tabindex="-1">与 XiHan.Framework 的关系 <a class="header-anchor" href="#与-xihan-framework-的关系" aria-label="Permalink to “与 XiHan.Framework 的关系”">​</a></h2><p>框架只提供通用能力与 Provider：令牌校验、策略判定、仓储、工作单元、租户目录、授予存储、操作审计、调度、工作流引擎、对象存储、本地化。BasicApp 在其上实现业务：签发令牌与会话、角色与授权规则、租户开通、菜单、日志查询、通知渠道等。框架没有、或属于应用的能力（SignalR Hub、OAuth 服务端、模板引擎、第三方登录），都是 BasicApp 自己的能力包。</p><p>后端以 NuGet 包引用 XiHan.Framework，版本写在 <code>backend/props/framework.props</code>，克隆本仓库即可构建；连框架源码调试时打开 <code>backend/XiHanFun.Local.slnx</code>，以 ProjectReference 引用同级检出、锁定在 <code>XiHanFrameworkCommit</code> 的框架源码。细节见<a href="./dev-environment#框架引用">框架引用</a>。</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};